#include <time.h>
#include "config.h"

// Returns 1 if currently in maintenance window, 0 otherwise.
int is_in_maintenance_window(const AppConfig* config) {
    if (config->maintenance_start_hour < 0 || config->maintenance_end_hour < 0) {
        return 0; // Feature disabled
    }

    time_t now = time(NULL);
    struct tm* tm_now = localtime(&now);
    int current_hour = tm_now->tm_hour;

    int start = config->maintenance_start_hour;
    int end = config->maintenance_end_hour;

    // Handle overnight window (e.g., 22:00 - 02:00)
    if (start > end) {
        return (current_hour >= start || current_hour < end);
    } else { // Handle same-day window (e.g., 09:00 - 17:00)
        return (current_hour >= start && current_hour < end);
    }
}
```

